async function getWordChoices(settings = {}) {
  const { gameMode = 'standard', selectedGenres, customWords, wordCount = 3 } = settings;

  let pool = [];

  if (gameMode === 'wordle') {
    pool = [...wordBank.wordle];
  } else if (gameMode === 'custom') {
    pool = [...(customWords || [])];
  } else if (gameMode === 'genre' && selectedGenres && selectedGenres.length > 0) {
    // Try Gemini AI for specific genre requests first
    const aiWords = await generateAIWords(settings);
    if (aiWords) return aiWords;

    selectedGenres.forEach(genre => {
      const key = genre.toLowerCase().replace(/[^a-z]/g, '');
      const keyMap = {
        'animals':           'animals',
        'fooddrink':         'foodAndDrink',
        'nature':            'nature',
        'entertainment':     'entertainment',
        'videogames':        'videoGames',
        'animemanga':        'anime',
        'historicalfigures': 'historical',
        'brandslogos':       'brands',
        'spacescifi':        'space',
        'idioms':            'idioms',
        'wordle':            'wordle',
        'wordlemode':        'wordle',
      };
      const bankKey = keyMap[key];
      if (bankKey && wordBank[bankKey]) {
        pool = [...pool, ...wordBank[bankKey]];
      }
    });
  } else {
    // Standard mode — draws from the massive standard list, Wordle words, and all genre categories
    pool = [
      ...wordBank.standard,
      ...wordBank.wordle,
      ...wordBank.animals,
      ...wordBank.foodAndDrink,
      ...wordBank.nature,
      ...wordBank.entertainment,
      ...wordBank.videoGames,
      ...wordBank.anime,
      ...wordBank.historical,
      ...wordBank.brands,
      ...wordBank.space,
      ...wordBank.idioms,
    ];
  }

  // Deduplicate, shuffle, return wordCount+1 choices
  const uniquePool = [...new Set(pool)];
  const shuffled = uniquePool.sort(() => Math.random() - 0.5);
  return shuffled.slice(0, wordCount + 1);
}

module.exports = { wordBank, getWordChoices };